void jnative_ui_list_clear(int32_t id) {
    if (id <= 0 || id >= JN_UI_MAX) {
        return;
    }
    g_item_count[id] = 0;
    if (g_win32_active && g_hwnds[id] != NULL
            && (g_kinds[id] == JN_UI_KIND_LISTVIEW || g_kinds[id] == JN_UI_KIND_TABLEVIEW)) {
        HWND lv = g_hwnds[id];
        /* Freeze paint across clear+bulk insert (Task Monitor refreshes ~1Hz). */
        SendMessageW(lv, WM_SETREDRAW, FALSE, 0);
        ListView_DeleteAllItems(lv);
        /* Keep HIMAGELIST + path→index cache across refreshes to avoid icon flicker
         * and repeated ExtractIconEx work. Cache is freed on control destroy. */
    }
}
void jnative_ui_list_add_item(int32_t id, const char *text) {
    if (id <= 0 || id >= JN_UI_MAX) {
        return;
    }
    if (!g_win32_active || g_hwnds[id] == NULL
            || (g_kinds[id] != JN_UI_KIND_LISTVIEW && g_kinds[id] != JN_UI_KIND_TABLEVIEW)) {
        g_item_count[id]++;
        return;
    }
    HWND lv = g_hwnds[id];
    char *copy = _strdup(text == NULL ? "" : text);
    if (copy == NULL) {
        return;
    }
    char *p = copy;
    char *tab = strchr(p, '\t');
    if (tab != NULL) {
        *tab = '\0';
    }
    int row = ListView_GetItemCount(lv);
    wchar_t *w0 = utf8_to_wide(p);
    LVITEMW item;
    memset(&item, 0, sizeof(item));
    item.mask = LVIF_TEXT | LVIF_PARAM;
    item.iItem = row;
    item.iSubItem = 0;
    item.pszText = w0;
    item.lParam = 0;
    ListView_InsertItem(lv, &item);
    free(w0);
    int sub = 1;
    int cols = g_col_count[id];
    const char *iconPath = NULL; /* first field past the declared columns */
    p = (tab == NULL) ? NULL : (tab + 1);
    while (p != NULL) {
        tab = strchr(p, '\t');
        if (tab != NULL) {
            *tab = '\0';
        }
        if (cols > 0 && sub >= cols) {
            /* Remaining TSV field is the icon path (UTF-8), not a cell. */
            if (iconPath == NULL) {
                iconPath = p;
            }
            sub++;
            p = (tab == NULL) ? NULL : (tab + 1);
            continue;
        }
        wchar_t *w = utf8_to_wide(p);
        LVITEMW subitem;
        memset(&subitem, 0, sizeof(subitem));
        subitem.mask = LVIF_TEXT;
        subitem.iItem = row;
        subitem.iSubItem = sub;
        subitem.pszText = w;
        if (SendMessageW(lv, LVM_SETITEMW, 0, (LPARAM)&subitem) == 0) {
            SendMessageW(lv, LVM_SETITEMTEXTW, (WPARAM)row, (LPARAM)&subitem);
        }
        free(w);
        sub++;
        p = (tab == NULL) ? NULL : (tab + 1);
    }
    if (iconPath != NULL && strncmp(iconPath, "jn:kind:section", 15) == 0) {
        LVITEMW pk;
        memset(&pk, 0, sizeof(pk));
        pk.mask = LVIF_PARAM;
        pk.iItem = row;
        pk.lParam = 1;
        SendMessageW(lv, LVM_SETITEMW, 0, (LPARAM)&pk);
    }
    if (iconPath != NULL || g_table_il[id] != NULL) {
        LVITEMW img;
        memset(&img, 0, sizeof(img));
        img.mask = LVIF_IMAGE;
        img.iItem = row;
        img.iSubItem = 0;
        img.iImage = I_IMAGENONE;
        if (iconPath != NULL && strncmp(iconPath, "jn:kind:section", 15) != 0) {
            int ii = table_icon_index(id, iconPath);
            if (ii >= 0) {
                img.iImage = ii;
            }
        }
        SendMessageW(lv, LVM_SETITEMW, 0, (LPARAM)&img);
    }
    free(copy);
    g_item_count[id] = ListView_GetItemCount(lv);
}
